function passwordControl(id,name,autocomplete,label){return `<span class="password-control"><input id="${id}" name="${name}" type="password" autocomplete="${autocomplete}" minlength="8" maxlength="128" required><button class="password-toggle" type="button" data-password-toggle="${id}" aria-label="${label} 표시" aria-pressed="false">${passwordEyeIcon}</button></span>`;}
let postcodeServicePromise;
function loadPostcodeService(){
 if(window.kakao?.Postcode)return Promise.resolve(window.kakao.Postcode);
 if(!postcodeServicePromise)postcodeServicePromise=new Promise((resolve,reject)=>{
  const script=document.createElement('script');
  script.src='https://t1.kakaocdn.net/mapjsapi/bundle/postcode/prod/postcode.v2.js';
  script.onload=()=>window.kakao?.Postcode?resolve(window.kakao.Postcode):reject(Error('주소 검색 서비스를 불러오지 못했습니다.'));
  script.onerror=()=>reject(Error('주소 검색 서비스를 불러오지 못했습니다.'));
  document.head.append(script);
 });
 return postcodeServicePromise;
}
function addressFromPostcode(data){
 const address=data.userSelectedType==='R'?data.roadAddress:data.jibunAddress;
 const extra=data.userSelectedType==='R'?[data.bname&&/[동로가]$/.test(data.bname)?data.bname:'',data.buildingName&&data.apartment==='Y'?data.buildingName:''].filter(Boolean).join(', '):'';
 return {postcode:data.zonecode||'',address:extra?`${address} (${extra})`:address};
}

function updateMemberNav(){const link=$('#member-nav'),admin=$('#admin-nav');if(!link||!admin)return;if(member){link.href='#account';link.className='header-icon header-login header-member-icon';link.dataset.memberName=member.name+' 님';link.setAttribute('aria-label',member.name+' 님 내 계정');link.innerHTML=loginIcon;admin.hidden=member.role!=='admin';}else{link.href='#login';link.className='header-icon header-login';delete link.dataset.memberName;link.setAttribute('aria-label','로그인');link.innerHTML=loginIcon;admin.hidden=true;}}
function updateCartCount(){const count=$('#cart-count');if(count)count.textContent=cart.reduce((a,i)=>a+i.quantity,0);}
function clearCart(){cart=[];cartOwner='';localStorage.removeItem('artell-cart');localStorage.removeItem('artell-cart-owner');updateCartCount();}
function setMember(next){if(!next||(cartOwner&&cartOwner!==next.id))clearCart();member=next;if(member&&!cartOwner){cartOwner=member.id;localStorage.setItem('artell-cart-owner',cartOwner);}updateMemberNav();}
function loginGate(title,target){pendingHash=target||location.hash||'#products';app.innerHTML=`<section class="auth-gate"><span class="eyebrow">MEMBERS ONLY</span><h1>${esc(title)}</h1><p>회원가입 또는 로그인 후 디자인을 만들고, 주문 내역을 계정에서 계속 확인할 수 있습니다.</p><div class="actions"><a class="primary" href="#login">로그인</a><a class="secondary" href="#signup">회원가입</a></div></section>`;}
